class Solution:
    def countSumsInBounds(self, nums: List[int], lower: int, upper: int) -> int:
        n, count = len(nums), 0
        for i in range(n):
            s = 0
            for j in range(i, n):
                s += nums[j]
                if lower <= s <= upper:
                    count += 1
        return count

