class Solution {
    public long countSumsInBounds(int[] nums, int lower, int upper) {
        int n = nums.length;
        long count = 0;
        for (int i = 0; i < n; i++) {
            long s = 0;
            for (int j = i; j < n; j++) {
                s += nums[j];
                if (s >= lower && s <= upper) count++;
            }
        }
        return count;
    }
}

