class Solution {
    private int lower, upper;

    public long countSumsInBounds(int[] nums, int lower, int upper) {
        this.lower = lower;
        this.upper = upper;
        int n = nums.length;
        long[] p = new long[n + 1];
        for (int i = 0; i < n; i++) p[i + 1] = p[i] + nums[i];
        return sortCount(p, new long[n + 1], 0, n + 1);
    }

    private long sortCount(long[] p, long[] tmp, int lo, int hi) {
        if (hi - lo <= 1) return 0;
        int mid = (lo + hi) >>> 1;
        long count = sortCount(p, tmp, lo, mid) + sortCount(p, tmp, mid, hi);
        int a = mid, b = mid;
        for (int i = lo; i < mid; i++) {
            while (a < hi && p[a] - p[i] < lower) a++;
            while (b < hi && p[b] - p[i] <= upper) b++;
            count += b - a;
        }
        int i = lo, j = mid, k = lo;
        while (i < mid && j < hi) tmp[k++] = p[i] <= p[j] ? p[i++] : p[j++];
        while (i < mid) tmp[k++] = p[i++];
        while (j < hi) tmp[k++] = p[j++];
        System.arraycopy(tmp, lo, p, lo, hi - lo);
        return count;
    }
}

