class Solution {
    long long lower, upper;
    vector<long long> p, tmp;

    long long sortCount(int lo, int hi) {
        if (hi - lo <= 1) return 0;
        int mid = lo + (hi - lo) / 2;
        long long count = sortCount(lo, mid) + sortCount(mid, hi);
        int a = mid, b = mid;
        for (int i = lo; i < mid; i++) {
            while (a < hi && p[a] - p[i] < lower) a++;
            while (b < hi && p[b] - p[i] <= upper) b++;
            count += b - a;
        }
        merge(p.begin() + lo, p.begin() + mid, p.begin() + mid, p.begin() + hi, tmp.begin() + lo);
        copy(tmp.begin() + lo, tmp.begin() + hi, p.begin() + lo);
        return count;
    }

public:
    long long countSumsInBounds(vector<int>& nums, int lower, int upper) {
        this->lower = lower;
        this->upper = upper;
        int n = nums.size();
        p.assign(n + 1, 0);
        for (int i = 0; i < n; i++) p[i + 1] = p[i] + nums[i];
        tmp.assign(n + 1, 0);
        return sortCount(0, n + 1);
    }
};

