static long long gLower, gUpper;

static long long sortCount(long long* p, long long* tmp, int lo, int hi) {
    if (hi - lo <= 1) return 0;
    int mid = lo + (hi - lo) / 2;
    long long count = sortCount(p, tmp, lo, mid) + sortCount(p, tmp, mid, hi);
    int a = mid, b = mid;
    for (int i = lo; i < mid; i++) {
        while (a < hi && p[a] - p[i] < gLower) a++;
        while (b < hi && p[b] - p[i] <= gUpper) b++;
        count += b - a;
    }
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) tmp[k++] = p[i] <= p[j] ? p[i++] : p[j++];
    while (i < mid) tmp[k++] = p[i++];
    while (j < hi) tmp[k++] = p[j++];
    memcpy(p + lo, tmp + lo, (hi - lo) * sizeof(long long));
    return count;
}

long long countSumsInBounds(int* nums, int numsSize, int lower, int upper) {
    gLower = lower;
    gUpper = upper;
    long long* p = malloc((numsSize + 1) * sizeof(long long));
    long long* tmp = malloc((numsSize + 1) * sizeof(long long));
    p[0] = 0;
    for (int i = 0; i < numsSize; i++) p[i + 1] = p[i] + nums[i];
    long long count = sortCount(p, tmp, 0, numsSize + 1);
    free(p);
    free(tmp);
    return count;
}
